// TFT arena concept. Traits, costs, item suggestions and match events are authored fixtures.
const arenaUnits={
  garen:{cost:1,traits:['Vanguard','Protector'],role:'Frontline'},leona:{cost:2,traits:['Vanguard','Mystic'],role:'Frontline'},
  ahri:{cost:4,traits:['Mage','Mystic'],role:'Magic'},lux:{cost:3,traits:['Mage','Protector'],role:'Magic'},
  ashe:{cost:3,traits:['Ranger','Mystic'],role:'Ranged'},lulu:{cost:2,traits:['Mage','Mystic'],role:'Support'},
  jinx:{cost:4,traits:['Ranger','Scrapper'],role:'Ranged'},yasuo:{cost:1,traits:['Vanguard','Scrapper'],role:'Frontline'}
};
const arenaTraits={Vanguard:{glyph:'⬟',steps:[2,4],note:'A stronger front row.'},Mystic:{glyph:'✧',steps:[2,4],note:'Give the team room to recover.'},Mage:{glyph:'✦',steps:[3,5],note:'Let your spellcasters work together.'},Ranger:{glyph:'➶',steps:[2,4],note:'A second source of backline pressure.'},Protector:{glyph:'◈',steps:[2,4],note:'Keep your damage dealers covered.'},Scrapper:{glyph:'⚒',steps:[2,4],note:'Make room for an unexpected pairing.'}};
const arenaItems=[{id:'bow',name:'Recurve Bow',icon:'assets/item-1043.png',hint:'Attack-speed component'},{id:'rod',name:'Needlessly Large Rod',icon:'assets/item-1058.png',hint:'Spell-power component'},{id:'sword',name:'B. F. Sword',icon:'assets/item-1038.png',hint:'Attack-damage component'}];
const arenaAugments=[
  [{name:'Jeweled Lotus',glyph:'✦',note:'A spell-focused direction for the carry.'},{name:'Component Grab Bag',glyph:'◈',note:'More components to shape the item plan.'},{name:'Second Wind',glyph:'❋',note:'A little staying power for a longer fight.'}],
  [{name:'Stand United',glyph:'⬟',note:'Reward a team with several active traits.'},{name:'Second Wind',glyph:'❋',note:'Help the frontline stay in the fight.'},{name:'Component Grab Bag',glyph:'◈',note:'Turn extra components into a flexible finish.'}],
  [{name:'Combat Training',glyph:'⚔',note:'Commit to an attack-focused carry.'},{name:'Component Grab Bag',glyph:'◈',note:'Find the next piece of the item plan.'},{name:'Second Wind',glyph:'❋',note:'Give the backline another chance to fire.'}]
];
let arenaAugment=0;
let arenaFilter='All',arenaInspect='ahri',arenaTrait='',arenaHistoryFilter='All';
let arenaUpgrades={};
try{const raw=JSON.parse(localStorage.getItem('queuepop-tft-arena-v1')||'{}');for(const [key,val]of Object.entries(raw)){if(/^[0-2]:(garen|leona|ahri|lux|ashe|lulu|jinx|yasuo)$/.test(key)&&val&&typeof val==='object')arenaUpgrades[key]={stars:[1,2,3].includes(val.stars)?val.stars:1,items:Array.isArray(val.items)?val.items.filter(i=>arenaItems.some(a=>a.id===i)).slice(0,3):[]};}}catch{}
const arenaSave=()=>{try{localStorage.setItem('queuepop-tft-arena-v1',JSON.stringify(arenaUpgrades));}catch{toast('Your browser could not save these unit settings.');}};
const arenaBoard=()=>state.board||formations[state.plan].board;
const arenaConfig=(id,plan=state.plan)=>arenaUpgrades[`${plan}:${id}`]||{stars:1,items:[]};
const arenaSample=(id,plan,phase=2)=>({stars:phase===0?1:phase===2&&id===formations[plan].carry?3:2,items:id===formations[plan].carry?['bow','rod','sword'].slice(0,phase+1):[]});
function arenaCompanion(){return `<svg class="arena-companion" viewBox="0 0 130 145" role="img" aria-label="A small feathered tactician cheering for your team"><ellipse cx="65" cy="132" rx="42" ry="8" fill="#102f35" opacity=".3"/><path d="M30 100 17 119l28-1m49-18 20 19-28-1" fill="#d8ae57"/><path d="M38 45q-20 13-15 53l-13 10 18 4q12 21 38 20 37 0 41-31 7-42-23-57L68 14 51 43Z" fill="#536d80" stroke="#1d3b48" stroke-width="4"/><path d="M65 52q-28-23-32 28-4 41 33 43 37-2 32-44-3-45-33-27" fill="#eee8cf"/><path d="m51 19 17-6 10 18-26 5Z" fill="#75d4b9"/><circle cx="47" cy="70" r="7" fill="#20343f"/><circle cx="82" cy="70" r="7" fill="#20343f"/><circle cx="49" cy="67" r="2" fill="white"/><circle cx="84" cy="67" r="2" fill="white"/><path d="m57 82 9 9 10-10Z" fill="#e6a448"/><path d="M43 102q23 14 43-1" fill="none" stroke="#b2c4b7" stroke-width="3"/><path d="m109 36 3 7 7 2-7 3-3 7-3-7-7-3 7-2Z" fill="#f5d071"/></svg>`;}
function tftNavigation(page){return `<nav class="arena-nav" aria-label="TFT navigation"><a href="#/tft" class="arena-brand"><span>⬡</span><b>TEAMFIGHT<br>TACTICS</b></a><div>${[['','My arena'],['comps','Team comps'],['planner','Team builder'],['history','Match history']].map(([p,n])=>`<a href="#/tft${p?'/'+p:''}" ${page===p?'aria-current="page"':''}>${n}</a>`).join('')}</div><span class="arena-demo">Sandbox roster</span></nav>`;}
function arenaTraitCounts(board){const counts={};for(const id of new Set(Object.values(board)))for(const t of arenaUnits[id].traits)counts[t]=(counts[t]||0)+1;return Object.entries(arenaTraits).map(([name,t])=>({name,...t,count:counts[name]||0})).sort((a,b)=>Number(b.count>=b.steps[0])-Number(a.count>=a.steps[0])||b.count-a.count);}
function arenaTraitsMarkup(board,interactive=false){return `<div class="arena-traits">${arenaTraitCounts(board).filter(t=>t.count).map(t=>{const active=t.steps.filter(n=>n<=t.count).pop()||0,next=t.steps.find(n=>n>t.count)||t.steps.at(-1);const tag=interactive?'button':'div';return `<${tag} class="arena-trait ${active?'active':''} ${arenaTrait===t.name&&interactive?'inspected':''}" ${interactive?`data-arena-trait="${t.name}" aria-pressed="${arenaTrait===t.name}"`:''}><span class="trait-emblem">${t.glyph}</span><span><b>${t.name}</b><small>${t.steps.map(n=>`<i class="${t.count>=n?'reached':''}">${n}</i>`).join('')}</small></span><strong>${t.count}<small>/${next}</small></strong></${tag}>`;}).join('')}</div>`;}
function arenaPiece(id,config){const u=arenaUnits[id];return `<span class="piece-stars" aria-hidden="true">${'★'.repeat(config.stars)}</span><span class="piece-portrait" style="--tier:var(--tier-${u.cost})">${icon(id)}</span><span class="piece-name">${units[id]}</span>${config.items.length?`<span class="piece-items">${config.items.map(i=>`<img src="${arenaItems.find(a=>a.id===i).icon}" alt="${arenaItems.find(a=>a.id===i).name}">`).join('')}</span>`:''}`;}
function arenaBoardMarkup(board,{editable=false,mini=false,plan=state.plan,sample=false,samplePhase=2}={}){return `<div class="arena-ground ${mini?'mini':''}"><div class="arena-edge edge-top"></div><div class="arena-grid" aria-label="Team positioning board">${Array.from({length:4},(_,r)=>`<div class="arena-row">${Array.from({length:7},(_,c)=>{const index=r*7+c,id=board[index],cfg=id?(sample?arenaSample(id,plan,samplePhase):arenaConfig(id,plan)):null,tag=editable?'button':'div';return `<${tag} class="arena-cell ${id?'has-unit':''} ${editable&&selectedCell===index?'picked':''} ${id&&arenaTrait&&editable&&arenaUnits[id].traits.includes(arenaTrait)?'trait-match':''}" ${editable?`data-cell="${index}" aria-label="Row ${r+1}, position ${c+1}: ${id?units[id]+', '+cfg.stars+' star':'empty'}" aria-pressed="${selectedCell===index}"`:id?`role="img" aria-label="${units[id]}, ${cfg.stars} star"`:'aria-hidden="true"'}>${id?arenaPiece(id,cfg):'<span class="empty-hex">+</span>'}</${tag}>`;}).join('')}</div>`).join('')}</div><span class="arena-front-label">Frontline</span><span class="arena-back-label">Backline</span><div class="arena-edge edge-bottom"></div></div>`;}
function arenaBench(board,editable=false){const available=Object.keys(units).filter(id=>!Object.values(board).includes(id));return `<div class="arena-bench"><span class="bench-title">Bench <small>${available.length} available</small></span><div>${available.map(id=>editable?`<button data-unit="${id}" aria-pressed="${selectedUnit===id}" aria-label="Place ${units[id]}">${icon(id)}<span>${units[id]}</span></button>`:`<span>${icon(id)}<small>${units[id]}</small></span>`).join('')||'<p>Everyone’s on the board. Select a unit to move or return it.</p>'}${Array.from({length:Math.max(0,5-available.length)},()=>'<i class="bench-slot" aria-hidden="true"></i>').join('')}</div></div>`;}
function arenaScene(board,options={}){return `<div class="arena-stage">${arenaBoardMarkup(board,options)}${options.mini?'':`<div class="tactician-perch">${arenaCompanion()}</div>${options.sample?'':arenaBench(board,options.editable)}`}</div>`;}
const arenaFootnote=()=>`<p class="arena-footnote">Concept sandbox · Trait assignments, costs, item setups and match events are illustrative, not a live TFT set.</p>`;
function tftWorldOverview(){const f=formations[state.plan],b=arenaBoard();return `${tftNavigation('')}<section class="arena-shell"><header class="arena-heading"><div><p>Your arena</p><h1>What are we playing?</h1></div><a class="arena-primary" href="#/tft/planner">Build your team <span>↗</span></a></header><div class="arena-home-layout"><aside class="arena-home-rail"><h2>Try a starting team</h2><div class="arena-team-picks">${formations.map((f,i)=>`<button data-arena-plan="${i}" aria-pressed="${state.plan===i}"><span class="team-pick-icons">${[f.carry,i===0?'lux':i===1?'leona':'ashe'].map(id=>icon(id)).join('')}</span><b>${f.name}</b><small>${['Spell pressure','Frontline first','Backline damage'][i]}</small></button>`).join('')}</div><div class="arena-hello">${arenaCompanion()}<p>Your pieces.<br><b>Your next clever idea.</b></p></div></aside><section class="arena-home-board"><div class="arena-table-heading"><div><span>Your saved formation</span><h2>${f.name}</h2></div><span class="arena-level">${Object.keys(b).length}<small>units</small></span></div>${arenaScene(b)}<div class="arena-board-footer"><span>Move pieces. Find a combination.</span><a href="#/tft/planner">Open team builder ↗</a></div></section><aside class="arena-synergy-rail"><h2>Team synergies</h2>${arenaTraitsMarkup(b)}<p>Each unique unit counts once. Try another team to see the balance change.</p></aside></div><div class="arena-home-bottom"><a href="#/tft/comps"><span>▦</span><div><h2>Find your next comp</h2><p>Compare the whole team, then make it yours.</p></div><b>↗</b></a><a href="#/tft/history"><span class="mini-placement">1<small>st</small></span><div><h2>Last board, new ideas</h2><p>Look back at your sample matches.</p></div><b>↗</b></a></div>${arenaFootnote()}</section>`;}
function arenaRoster(board,plan,sample=false){return `<div class="arena-roster">${Object.values(board).map(id=>`<span style="--tier:var(--tier-${arenaUnits[id].cost})">${arenaPiece(id,sample?arenaSample(id,plan):arenaConfig(id,plan))}</span>`).join('')}</div>`;}
function tftCollection(){return `${tftNavigation('comps')}<section class="arena-shell"><header class="arena-heading"><div><p>Team comps</p><h1>Find the pieces that click.</h1></div><span class="arena-muted">3 starting points. Plenty of room to pivot.</span></header><div class="arena-comps">${formations.map((f,i)=>`<article class="arena-comp"><div class="comp-board-preview">${arenaBoardMarkup(f.board,{mini:true,plan:i,sample:true})}<span class="comp-unit-count">7-unit example</span></div><div class="arena-comp-info"><span class="comp-archetype">${['Spell pressure','Frontline first','Backline damage'][i]}</span><h2>${f.name}</h2><p>${f.text}</p><div class="comp-trait-strip">${arenaTraitCounts(f.board).filter(t=>t.count>=t.steps[0]).map(t=>`<span>${t.glyph} <b>${t.count}</b> ${t.name}</span>`).join('')}</div><div class="comp-carry-line">${icon(f.carry)}<span>Carry focus<b>${units[f.carry]}</b></span><div class="comp-items">${arenaItems.map(a=>`<img src="${a.icon}" alt="${a.name}" title="${a.name}">`).join('')}</div></div><button class="arena-primary" data-plan="${i}">Open in builder <span>↗</span></button><small>${state.savedComps.includes(i)?'✓ Saved team · opens your edits':'Opens your remembered version'}</small></div></article>`).join('')}</div>${arenaFootnote()}</section>`;}
function arenaInspector(){const board=arenaBoard(),id=selectedCell!==null&&board[selectedCell]?board[selectedCell]:selectedUnit||arenaInspect,u=arenaUnits[id],cfg=arenaConfig(id),onBoard=Object.values(board).includes(id);return `<aside class="arena-inspector"><div class="workshop-heading"><h2>Unit workshop</h2><button class="arena-text" data-arena-return>Back to board ↑</button></div><div class="inspector-identity" style="--tier:var(--tier-${u.cost})">${icon(id)}<div><h3>${units[id]}</h3><span>${u.role} · ${u.cost} gold</span></div></div><div class="unit-trait-tags">${u.traits.map(t=>`<span>${arenaTraits[t].glyph} ${t}</span>`).join('')}</div><fieldset><legend>Star level</legend><div class="arena-stars-picker">${[1,2,3].map(n=>`<button data-arena-stars="${n}" data-arena-unit="${id}" aria-label="${n} star ${units[id]}" aria-pressed="${cfg.stars===n}">${'★'.repeat(n)}</button>`).join('')}</div></fieldset><fieldset><legend>Item slots <small>${cfg.items.length}/3</small></legend><div class="arena-item-slots">${Array.from({length:3},(_,i)=>{const a=arenaItems.find(a=>a.id===cfg.items[i]);return a?`<button data-arena-remove-item="${i}" data-arena-unit="${id}" aria-label="Remove ${a.name}"><img src="${a.icon}" alt="">×</button>`:'<span>+</span>';}).join('')}</div><div class="arena-item-options">${arenaItems.map(a=>`<button data-arena-equip="${a.id}" data-arena-unit="${id}" ${cfg.items.length===3?'disabled':''}><img src="${a.icon}" alt=""><span>${a.name}<small>${a.hint}</small></span><b>+</b></button>`).join('')}</div></fieldset><p class="inspector-status">${onBoard?'On your board · changes save automatically':'Choose this unit from the tray to place it.'}</p>${selectedCell!==null?'<button class="arena-secondary" data-action="remove-unit">Return to bench</button>':''}</aside>`;}
function tftArenaPlanner(){const b=arenaBoard(),f=formations[state.plan];return `${tftNavigation('planner')}<section class="arena-shell"><header class="arena-heading"><div><p>Team builder</p><h1>Cook up a comp.</h1></div><div class="arena-builder-actions"><label class="sr-only" for="formation">Formation</label><select id="formation">${formations.map((f,i)=>`<option value="${i}" ${i===state.plan?'selected':''}>${f.name}</option>`).join('')}</select><button class="arena-primary" data-action="save-comp" aria-pressed="${state.savedComps.includes(state.plan)}">${state.savedComps.includes(state.plan)?'✓ Saved':'Save team'}</button></div></header><div class="arena-builder-layout"><aside class="arena-synergy-rail"><h2>Team synergies</h2>${arenaTraitsMarkup(b,true)}<p class="trait-explanation" aria-live="polite">${arenaTrait?arenaTraits[arenaTrait].note:'Select a trait to highlight its units.'}</p></aside><section class="arena-builder-center"><div class="arena-table-heading"><h2>${f.name}</h2><span class="arena-level">${Object.keys(b).length}<small>units</small></span></div>${arenaScene(b,{editable:true})}<div class="arena-board-footer"><span role="status">${selectedUnit?`Choose a hex for ${units[selectedUnit]}.`:selectedCell!==null?'Choose a hex to move or swap this unit.':'Select a piece to move it or change its setup.'}</span><div class="arena-board-tools"><button class="arena-text" data-arena-workshop>Edit ${units[selectedCell!==null&&b[selectedCell]?b[selectedCell]:selectedUnit||arenaInspect]}</button><button class="arena-text" data-action="reset-board">Reset positions</button></div></div><section class="arena-shop"><div class="shop-heading"><h2>Unit tray</h2><span>Select a unit, then a hex.</span></div><div class="arena-filters" aria-label="Unit roles">${['All','Frontline','Magic','Ranged','Support'].map(x=>`<button data-arena-filter="${x}" aria-pressed="${arenaFilter===x}">${x}</button>`).join('')}</div><div class="arena-shop-units">${Object.entries(arenaUnits).filter(([,u])=>arenaFilter==='All'||u.role===arenaFilter).map(([id,u])=>`<button data-unit="${id}" aria-pressed="${selectedUnit===id}" style="--tier:var(--tier-${u.cost})">${icon(id)}<span class="shop-cost">${u.cost}</span><b>${units[id]}</b><small>${u.traits.join(' / ')}</small>${Object.values(b).includes(id)?'<i>On board</i>':''}</button>`).join('')}</div></section></section>${arenaInspector()}</div>${arenaFootnote()}</section>`;}
function arenaAugmentStrip(plan){return `<div class="arena-augment-strip"><span>Augments</span>${arenaAugments[plan].map(a=>`<span title="${a.name}"><i aria-hidden="true">${a.glyph}</i><small>${a.name}</small></span>`).join('')}</div>`;}
function arenaAugmentReview(plan,phase){const selected=Math.min(arenaAugment,phase);return `<section class="arena-augment-review"><h3>Augment choices</h3><div>${arenaAugments[plan].map((a,i)=>`<button data-arena-augment="${i}" aria-pressed="${selected===i}" ${i>phase?'disabled':''} aria-label="${a.name}${i>phase?', later in the match':''}"><i>${a.glyph}</i><small>${i>phase?'Later':a.name}</small></button>`).join('')}</div><p>${arenaAugments[plan][selected].note}</p></section>`;}
function tftArenaHistory(id){const match=tftMatches.find(m=>m.id===id);if(match)return arenaReport(match);const matches=tftMatches.filter(m=>arenaHistoryFilter==='All'||(arenaHistoryFilter==='Top 4'?parseInt(m.place)<=4:parseInt(m.place)>4));return `${tftNavigation('history')}<section class="arena-shell"><header class="arena-heading"><div><p>Match history</p><h1>Your recent boards.</h1></div><span class="arena-muted">3 sample matches</span></header><div class="arena-history-summary"><div class="placement-track">${tftMatches.map(m=>`<a href="#/tft/history/${m.id}" class="place-${parseInt(m.place)<=4?'top':'out'}">${m.place}</a>`).join('')}</div><p>One win. Two top-four finishes.<br><b>Three boards worth a second look.</b></p><div class="arena-filters">${['All','Top 4','Bottom 4'].map(f=>`<button data-arena-history="${f}" aria-pressed="${arenaHistoryFilter===f}">${f}</button>`).join('')}</div></div><div class="arena-match-list">${matches.map(m=>{const f=formations[m.plan];return `<a class="arena-match-entry" href="#/tft/history/${m.id}"><div class="match-placement ${parseInt(m.place)<=4?'top':''}"><strong>${m.place}</strong><small>of 8</small></div><div class="match-team"><div class="match-entry-title"><h2>${f.name}</h2><span>${m.date} · ${m.stage}</span></div>${arenaRoster(f.board,m.plan,true)}<div class="match-traits">${arenaTraitCounts(f.board).filter(t=>t.count>=t.steps[0]).map(t=>`<span>${t.glyph} ${t.count} ${t.name}</span>`).join('')}</div>${arenaAugmentStrip(m.plan)}</div><div class="match-decision"><span>Turning point</span><p>${['Protected the carry','Stabilized the frontline','Waited to spend'][m.plan]}</p><b>Review board ↗</b></div></a>`;}).join('')}</div>${arenaFootnote()}</section>`;}
function arenaReport(m){const phase=reviewMoment,f=formations[m.plan],b=reviewBoard(m.plan,phase),notes=formationNotes[m.plan][phase];return `${tftNavigation('history')}<section class="arena-shell"><a class="arena-back" href="#/tft/history">← All matches</a><header class="arena-heading arena-report-heading"><div class="match-placement ${parseInt(m.place)<=4?'top':''}"><strong>${m.place}</strong><small>of 8</small></div><div><p>${m.date} · Sample match</p><h1>${f.name}</h1></div><button class="arena-primary" data-plan="${m.plan}">Open your formation ↗</button></header><div class="arena-timeline" aria-label="Match snapshots">${['Opening','Developing','Final board'].map((n,i)=>`<button data-moment="${i}" aria-pressed="${phase===i}"><span>${['2-1','3-2',m.stage][i]}</span><b>${n}</b><small>${['Find a frontline','Add your damage','The finished team'][i]}</small></button>`).join('')}</div><div class="arena-report-layout"><aside class="arena-synergy-rail"><h2>Board synergies</h2>${arenaTraitsMarkup(b)}</aside><section><div class="arena-table-heading"><h2>${['The first pieces','Taking shape','The final board'][phase]}</h2><span class="arena-muted">${Object.keys(b).length} units · Sample snapshot</span></div>${arenaScene(b,{plan:m.plan,sample:true,samplePhase:phase})}</section><aside class="arena-match-analysis" aria-live="polite"><span class="analysis-symbol">${['⬟','✦','◈'][phase]}</span><p>${['Establish','Develop','Reposition'][phase]}</p><h2>${notes[0]}</h2><p>${notes[1]}</p><div><b>Take into your next game</b><p>${m.note}</p></div>${arenaAugmentReview(m.plan,phase)}<small>Illustrated stages, not a recorded replay. Your saved formation stays separate.</small></aside></div>${arenaFootnote()}</section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!b.closest('.tft-world'))return;let focus;
if(b.hasAttribute('data-arena-workshop')){$('.arena-stars-picker button').focus();return;}
if(b.hasAttribute('data-arena-return')){$(`[data-cell="${selectedCell??Object.keys(arenaBoard())[0]??0}"]`).focus();return;}
if(b.dataset.cell!==undefined&&arenaBoard()[b.dataset.cell])arenaInspect=arenaBoard()[b.dataset.cell];
if(b.dataset.unit)arenaInspect=b.dataset.unit;
if(b.dataset.arenaPlan!==undefined){state.plan=+b.dataset.arenaPlan;state.board=state.boards[state.plan]||null;selectedCell=null;selectedUnit=null;persist();focus=`[data-arena-plan="${state.plan}"]`;}
if(b.dataset.arenaAugment!==undefined){arenaAugment=+b.dataset.arenaAugment;focus=`[data-arena-augment="${arenaAugment}"]`;}
if(b.dataset.arenaFilter){arenaFilter=b.dataset.arenaFilter;focus=`[data-arena-filter="${arenaFilter}"]`;}
if(b.dataset.arenaHistory){arenaHistoryFilter=b.dataset.arenaHistory;focus=`[data-arena-history="${arenaHistoryFilter}"]`;}
if(b.dataset.arenaTrait){arenaTrait=arenaTrait===b.dataset.arenaTrait?'':b.dataset.arenaTrait;focus=`[data-arena-trait="${b.dataset.arenaTrait}"]`;}
if(b.dataset.arenaUnit){const id=b.dataset.arenaUnit,cfg={...arenaConfig(id),items:[...arenaConfig(id).items]};arenaInspect=id;if(b.dataset.arenaStars){cfg.stars=+b.dataset.arenaStars;focus=`[data-arena-stars="${cfg.stars}"]`;}if(b.dataset.arenaEquip&&cfg.items.length<3){cfg.items.push(b.dataset.arenaEquip);focus='.arena-item-slots button:last-child';}if(b.dataset.arenaRemoveItem!==undefined){cfg.items.splice(+b.dataset.arenaRemoveItem,1);focus='.arena-item-options button';}arenaUpgrades[`${state.plan}:${id}`]=cfg;arenaSave();}
if(focus)rerenderKeepingFocus(focus);
});
